DROP TABLE IF EXISTS `data_subject_requests`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `data_subject_requests` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `PatientId` int NOT NULL,
  `RequestType` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `Status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `RequestedAtUtc` datetime(6) NOT NULL,
  `VerifiedAtUtc` datetime(6) DEFAULT NULL,
  `HipaaDueAtUtc` datetime(6) DEFAULT NULL,
  `ConsumerDueAtUtc` datetime(6) DEFAULT NULL,
  `CompletedAtUtc` datetime(6) DEFAULT NULL,
  `ExtensionReason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `ExtendedDueAtUtc` datetime(6) DEFAULT NULL,
  `DenialReason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `RequestNotes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `AmendmentPayloadJson` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `DownloadTokenHash` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `DownloadExpiresAtUtc` datetime(6) DEFAULT NULL,
  `ExportPayloadJson` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `PmsRemoteCopyNoted` tinyint(1) NOT NULL DEFAULT '0',
  `StaffNotes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  PRIMARY KEY (`Id`),
