INSERT INTO `patient_notifications` VALUES (1,18,'VoiceCallUpdate','Nuvi call update','The office confirmed a booking, but Nuvi could not capture the appointment date/time. Please confirm the slot with the office.',NULL,1194,1,'2026-08-08 11:16:22.332636'),(2,18,'VoiceCallUpdate','Nuvi call update','The office confirmed a booking, but Nuvi could not capture the appointment date/time. Please confirm the slot with the office.',NULL,1194,1,'2026-08-08 11:16:46.015425'),(3,18,'VoiceCallUpdate','Nuvi call update','The office confirmed a booking, but Nuvi could not capture the appointment date/time. Please confirm the slot with the office.',NULL,1194,1,'2026-08-08 11:18:04.141228'),(4,18,'VoiceCallUpdate','Nuvi call update','The office confirmed a booking, but Nuvi could not capture the appointment date/time. Please confirm the slot with the office.',NULL,1194,1,'2026-08-08 11:18:16.676216'),(5,18,'VoiceCallUpdate','Nuvi call update','The office confirmed a booking, but Nuvi could not capture the appointment date/time. Please confirm the slot with the office.',NULL,1194,1,'2026-08-12 05:31:26.227267'),(6,18,'AppointmentBooked','Appointment booked','Nuvi booked your visit with Dr. Moayad Mardini on Fri, Aug 14 · 2:00 PM (PST).',1,1194,1,'2026-08-12 05:31:35.562271'),(7,18,'AppointmentBooked','Appointment booked','Nuvi booked your visit with Dr. Moayad Mardini on Mon, Aug 17 · 3:00 PM (PST).',2,1194,1,'2026-08-12 05:49:35.870645'),(8,18,'VoiceCallUpdate','Cancel update','I wasn\'t able to reach The Houston Dentists — the office did not answer.',1,1194,1,'2026-08-12 10:57:59.188217'),(9,18,'VoiceCallUpdate','Cancel update','I wasn\'t able to reach The Houston Dentists — the office did not answer.',1,1194,1,'2026-08-12 11:34:47.090153'),(10,18,'VoiceCallUpdate','Nuvi call update','I\'ll retry Dr. Moayad Mardini after 2 minutes.',NULL,1194,1,'2026-08-12 11:43:27.642586'),(11,18,'VoiceCallUpdate','Nuvi call update','I couldn\'t book with any of your matched offices. Please call